cpp.setup:
auto* trigger = new fluent::basicinput::Button(QStringLiteral("Show Popup"), %PARENT%);
trigger->setFluentStyle(fluent::basicinput::Button::Accent);
trigger->setFixedSize(136, 32);
trigger->move(132, 104);
trigger->show();
auto* control = new fluent::dialogs_flyouts::Popup(%PARENT%);
control->setAnimationEnabled(false);
control->setLightDismissConsumesPress(true);
auto* layout = new QVBoxLayout(control);
layout->setContentsMargins(24, 20, 24, 20);
layout->setSpacing(8);
auto* header = new QHBoxLayout;
header->setSpacing(8);
auto* heading = new fluent::textfields::Label(QStringLiteral("Quick note"), control);
heading->setFluentTypography(Typography::FontRole::BodyStrong);
header->addWidget(heading, 1);
auto* closeButton = new fluent::basicinput::Button(control);
closeButton->setAccessibleName(QStringLiteral("Close popup"));
closeButton->setIconGlyph(Typography::Icons::ChromeClose);
closeButton->setFluentLayout(fluent::basicinput::Button::IconOnly);
closeButton->setFluentStyle(fluent::basicinput::Button::Subtle);
closeButton->setFixedSize(28, 28);
header->addWidget(closeButton);
layout->addLayout(header);
auto* body = new fluent::textfields::Label(QStringLiteral("Click outside, press Esc, or use the close button to dismiss."), control);
body->setWordWrap(true);
body->setTextColorRole(fluent::textfields::Label::TextColorRole::Secondary);
layout->addWidget(body);
control->resize(296, 134);
QObject::connect(closeButton, &fluent::basicinput::Button::clicked, control, &fluent::dialogs_flyouts::Popup::close);
QObject::connect(trigger, &fluent::basicinput::Button::clicked, control, &fluent::dialogs_flyouts::Popup::open);
control->open();
